import{c as t,Q as o,j as a,m as n}from"./chunks/framework.BXc4yaFE.js";const c=JSON.parse(`{"title":"Loop Engineering Isn't What You Think","description":"","frontmatter":{"url":"https://x.com/techwith_ram/status/2064925285003542820","title":"Loop Engineering Isn't What You Think","author":"𝗿𝗮𝗺𝗮𝗸𝗿𝘂𝘀𝗵𝗻𝗮— 𝗲/𝗮𝗰𝗰","archived":"2026-06-11T00:00:00.000Z","handle":"@techwith_ram","published":"2026-06-11T00:00:00.000Z","stats":"49 likes · 9 retweets · 53 bookmarks · 2793 views","tags":["loop-engineering","agentic-loops","code-review","human-in-the-loop","token-cost","agent-design"],"type":"twitter-article"},"headers":[],"relativePath":"research/tweets/2026-06-11-@techwith_ram-542820.md","filePath":"research/tweets/2026-06-11-@techwith_ram-542820.md","lastUpdated":1785909234000}`),s={name:"research/tweets/2026-06-11-@techwith_ram-542820.md"};function i(r,e,h,l,d,u){return o(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="loop-engineering-isn-t-what-you-think-—-techwith-ram" tabindex="-1">Loop Engineering Isn&#39;t What You Think — @techwith_ram <a class="header-anchor" href="#loop-engineering-isn-t-what-you-think-—-techwith-ram" aria-label="Permalink to &quot;Loop Engineering Isn&#39;t What You Think — @techwith_ram&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/techwith_ram/status/2064925285003542820" target="_blank" rel="noreferrer">https://x.com/techwith_ram/status/2064925285003542820</a><strong>作者</strong>：𝗿𝗮𝗺𝗮𝗸𝗿𝘂𝘀𝗵𝗻𝗮— 𝗲/𝗮𝗰𝗰（@techwith_ram） <strong>發布日期</strong>：2026-06-11 <strong>收錄日期</strong>：2026-06-11 <strong>類型</strong>：Twitter Article <strong>統計</strong>：49 likes · 9 retweets · 53 bookmarks · 2793 views</p><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><p>The people building the most advanced coding agents say they barely write prompts anymore. Instead, they build systems that generate, review, and improve their own work. The promise is seductive: less babysitting, more automation. But there&#39;s a catch. Most conversations about loops focus on what they can do, not what they cost. Every extra turn burns tokens, makes assumptions, and moves further away from your direct control.</p><h2 id="if-you-want-to-learn-ai-agents-check-out-this-github-repo" tabindex="-1">If you want to learn AI agents, check out this GitHub repo: <a class="header-anchor" href="#if-you-want-to-learn-ai-agents-check-out-this-github-repo" aria-label="Permalink to &quot;If you want to learn AI agents, check out this GitHub repo:&quot;">​</a></h2><h2 id="https-github-com-ramakm-ai-agents-git" tabindex="-1"><a href="https://github.com/Ramakm/ai-agents.git" target="_blank" rel="noreferrer">https://github.com/Ramakm/ai-agents.git</a> <a class="header-anchor" href="#https-github-com-ramakm-ai-agents-git" aria-label="Permalink to &quot;https://github.com/Ramakm/ai-agents.git&quot;">​</a></h2><p>There&#39;s a quote from Boris Cherny, the engineer behind Claude Code, that has made a lot of developers stop and think. When asked how he works today, he said he barely prompts models directly anymore. Instead, he has loops that prompt the models for him. His job is to build the loops. That&#39;s a subtle but important shift. He&#39;s no longer focused on talking to the AI. He&#39;s focused on building the system that talks to the AI. Peter Steinberger, creator of OpenClaw, makes a similar point: stop prompting coding agents and start designing loops that prompt them. Naturally, the AI world ran with it. Agentic loops became the latest buzzword. But as usual, the reality is more nuanced than the headline. Most people talking about loops can&#39;t clearly explain what they are, when they actually help, or what you&#39;re giving up in exchange for the automation. Let me fix that for you in this article!!</p><h1 id="first-what-is-a-loop" tabindex="-1">First, what is a &quot;loop&quot;? <a class="header-anchor" href="#first-what-is-a-loop" aria-label="Permalink to &quot;First, what is a &quot;loop&quot;?&quot;">​</a></h1><p>You&#39;ve been running a loop this whole time. You just had a human in it: you. You open Cursor, Claude Code, or Codex and type, &quot;Build me a landing page.&quot; You look at what comes back. The hero section doesn&#39;t feel right, so you ask for changes. It generates another version. You review it, redirect it, and repeat the process. Generate. Review. Redirect. Repeat. That cycle has a name: human-in-the-loop. The agent does the building, but you&#39;re still the one directing, judging, and steering the work. [圖 1 — 來源: The autonomous loop: a human starts it once, then the agent prompts itself on repeat. No driver. Just the engine.] This is comfortable because you catch drift early. The landing page looks off? You say so before a single line of auth code gets written. You are the quality gate, the taste, and the course correction, all rolled into one slow, attentive human.</p><h1 id="the-new-idea-take-the-human-out" tabindex="-1">The new idea: take the human out <a class="header-anchor" href="#the-new-idea-take-the-human-out" aria-label="Permalink to &quot;The new idea: take the human out&quot;">​</a></h1><p>The trend everyone&#39;s excited about flips the diagram. Instead of you closing the loop each time, you close it once. You hand the agent a spec, that is, a spec.md or PRD.md file describing what to build, &amp; then you step back. Check this repo: <a href="https://github.com/snarktank/ai-dev-tasks/blob/main/create-prd.md" target="_blank" rel="noreferrer">https://github.com/snarktank/ai-dev-tasks/blob/main/create-prd.md</a> The agent generates, reads its own output, decides what&#39;s left to do, and prompts itself again. Over and over, on its own, until it thinks the job is done. [圖 2 — 來源: The autonomous loop: a human starts it once, then the agent prompts itself on repeat. No driver. Just the engine.] This isn&#39;t a fringe idea. The open-source developer Geoffrey Huntley packaged the simplest version of it as the &quot;Ralph Wiggum&quot; loop. At its core, a Bash loop keeps re-running an agent on the same task until a clear finish condition is met. Tools like Cursor&#39;s /goal and the various /loop and /sloop commands floating around are all flavors of the same move: &quot;Here&#39;s the goal; don&#39;t stop until it&#39;s done.&quot; At Anthropic, this style of work is part of why Claude now authors the large majority of merged production code. It is, genuinely, a glimpse of where this is heading. But here&#39;s where the slide deck ends and reality begins.</p><h1 id="why-it-feels-like-magic-and-often-isn-t" tabindex="-1">Why it feels like magic and often isn&#39;t <a class="header-anchor" href="#why-it-feels-like-magic-and-often-isn-t" aria-label="Permalink to &quot;Why it feels like magic and often isn&#39;t&quot;">​</a></h1><p>Imagine hiring a brilliant developer, handing them a spec, and hearing nothing for two weeks. They come back with a finished product. Some decisions are spot on. Others completely miss what you had in mind. Not because they&#39;re bad. Because no spec captures everything. That&#39;s the problem with autonomous loops. The moment an agent starts making hundreds of decisions on your behalf, it&#39;s forced to fill in the gaps. And there are always gaps. What comes back can feel like a slot machine. Pull the lever, wait, and hope the output matches your vision. Sometimes it does. Often it doesn&#39;t. The hardest part is that you don&#39;t get to steer along the way. Once you type /goal, the train leaves the station.</p><h1 id="the-part-nobody-puts-on-the-slide-the-bill" tabindex="-1">The part nobody puts on the slide: the bill <a class="header-anchor" href="#the-part-nobody-puts-on-the-slide-the-bill" aria-label="Permalink to &quot;The part nobody puts on the slide: the bill&quot;">​</a></h1><p>Here&#39;s the uncomfortable reality: loops aren&#39;t free. A single request is one round of tokens. A loop might run ten, twenty, or fifty rounds, carrying context, outputs, and history through every step. The cost compounds fast. That&#39;s the quiet asterisk behind the whole agentic loop movement. Many of the people advocating for fully autonomous workflows operate with budgets large enough that token costs barely matter. Most developers don&#39;t have that luxury. If you&#39;re on a $20, $100, or even $200 monthly plan, an open-ended loop can burn through your budget surprisingly quickly. That&#39;s why companies have started putting limits on agent usage. The technology is powerful, but the economics matter. None of this means loops are a bad idea. It just means they&#39;re not magic. They&#39;re a tool, and like any powerful tool, you need to understand what it costs before you leave it running.</p><h1 id="so-when-does-a-loop-actually-work" tabindex="-1">So when does a loop actually work? <a class="header-anchor" href="#so-when-does-a-loop-actually-work" aria-label="Permalink to &quot;So when does a loop actually work?&quot;">​</a></h1><p>Here&#39;s a simple rule: loops work best when success is objective. Did the tests pass? Did the score clear the threshold? Does the output match the template? When the answer is a clear yes or no, a loop has something concrete to optimize for. The trouble starts when success becomes subjective. &quot;Does this feel right?&quot; &quot;Is this the product I imagined?&quot; &quot;Would customers love this?&quot; Those aren&#39;t questions an agent can reliably measure. At that point, the loop is guessing. That&#39;s why loops excel at things like generating hundreds of SEO pages from a fixed format, running evaluations, or handling large-scale code migrations. The target is clear, and the feedback stays consistent. [圖 3 — 來源: The honest map. Down in the fixed + binary corner, loops are a gift. Up in the creative + open-ended corner, they&#39;re a slot machine.] But &quot;build me a profitable startup&quot; is a completely different problem. There is no test suite for product-market fit. No benchmark for taste. No objective score for vision. The more subjective the goal, the more valuable human judgment becomes.</p><h1 id="a-loop-you-can-actually-run-today" tabindex="-1">A loop you can actually run today <a class="header-anchor" href="#a-loop-you-can-actually-run-today" aria-label="Permalink to &quot;A loop you can actually run today&quot;">​</a></h1><p>If there&#39;s one loop I&#39;d recommend to almost any developer, it&#39;s an automated code review loop. Why? Because it has something most agent workflows don&#39;t: a clear, objective signal. You push code to GitHub. A review agent like Greptile, CodeRabbit, or Macroscope reviews the changes and returns a score out of five. Then you set a simple rule: nothing ships below 4/5. [圖 4 — 來源: A loop worth running. The score is the fixed feedback; &quot;4/5 or higher&quot; is the binary gate. Everything else loops until it&#39;s met.] If the score comes back as 2/5 or 3/5, you don&#39;t jump in manually. You trigger a small workflow that reads the review, applies the suggested fixes, pushes the changes, and waits for the next review. The process repeats until the score clears 4/5 or the loop hits a maximum number of attempts. That&#39;s what a good loop looks like: a closed system with a measurable target and a clear exit condition. The secret isn&#39;t the loop itself. It&#39;s having a score the loop can reliably chase. If you want the bare-bones shape of it, a Ralph-style loop is honestly just a few lines around your agent:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># the whole idea, minus the ceremony</span></span>
<span class="line"><span>for i in $(seq 1 5); do</span></span>
<span class="line"><span>  agent run &quot;read the latest review, apply fixes, push&quot;</span></span>
<span class="line"><span>  score=$(get_review_score)            # the fixed, objective signal</span></span>
<span class="line"><span>  if [ &quot;$score&quot; -ge 4 ]; then</span></span>
<span class="line"><span>    echo &quot;passed at $score/5 — shipping&quot;; break</span></span>
<span class="line"><span>  fi</span></span>
<span class="line"><span>done</span></span></code></pre></div><p>Be warned: even this clean loop frays at the edges. Push more than ~1,000 lines in one go, and the review agent struggles to hold it all in context; you&#39;ll rarely hit 5/5. The fix is the same discipline good engineers already use: keep changes small, split big work into multiple PRs. Even inside a tidy, well-defined loop, scope is still the thing that breaks it.</p><h1 id="my-honest-take" tabindex="-1">My honest take <a class="header-anchor" href="#my-honest-take" aria-label="Permalink to &quot;My honest take&quot;">​</a></h1><p>None of this is a knock on the people pushing autonomous loops. They&#39;re probably early, not wrong. Self-healing agents, automated bug fixes, and systems that can see and test their own work are arriving faster than most people expected. But &quot;arriving&quot; &amp; &quot;ready for everything&quot; are two different things. The reality is that most great products aren&#39;t built on logic alone. They require taste, judgment, and a bunch of tiny decisions that no spec can fully capture. That&#39;s why I love this line: AI can replicate sauce, but it can&#39;t create sauce. Loops are incredible when the goal is clear. Reviews, tests, linting, migrations, template-based generation. Give them a measurable target and they&#39;ll work all day. But when the question becomes, &quot;Does this feel right?&quot; or &quot;Would people actually want this?&quot; you still need a human in the loop. So don&#39;t build a giant loop and ask it to create your startup. Build small loops around the boring, binary parts of the job, and keep your hands on the wheel for everything that needs taste and vision. That&#39;s not fighting the trend. It&#39;s understanding it. Follow @techwith_ram for more such content</p><hr><h2 id="研究摘要" tabindex="-1">研究摘要 <a class="header-anchor" href="#研究摘要" aria-label="Permalink to &quot;研究摘要&quot;">​</a></h2><p><strong>TL;DR</strong>：Loop Engineering 適用邊界 = 成功條件可客觀量化；主觀任務請保留 human-in-the-loop，code review loop 是最佳入門選擇。</p><h3 id="核心論點" tabindex="-1">核心論點 <a class="header-anchor" href="#核心論點" aria-label="Permalink to &quot;核心論點&quot;">​</a></h3><ol><li><strong>Loop 是什麼</strong>：human-in-the-loop 一直存在；自主 loop 是把人移出循環、讓 agent 以 spec.md 驅動自我迭代（Ralph Wiggum pattern）</li><li><strong>自主 loop 的隱藏代價</strong>：每輪都累積 tokens + context；沒有中途導向機會；spec 無法涵蓋所有邊界決策</li><li><strong>Loop 成功條件 = 目標必須客觀</strong>：tests pass / score threshold / template match → 明確 yes/no gate；主觀創意目標（&quot;feel right&quot;）→ 無可靠 feedback，loop 只是在猜</li><li><strong>實際可跑的 loop</strong>：code review loop（Greptile/CodeRabbit/Macroscope 打 5 分，gate = 4/5）+ 最大嘗試次數限制</li><li><strong>PR 大小是 loop 的隱形破壞者</strong>：&gt;1000 行讓 review agent 失去 context，難以達 5/5；保持小 PR 是 loop discipline 的一部分</li></ol><h3 id="關鍵數據-工具" tabindex="-1">關鍵數據 / 工具 <a class="header-anchor" href="#關鍵數據-工具" aria-label="Permalink to &quot;關鍵數據 / 工具&quot;">​</a></h3><ul><li>Ralph Wiggum loop：bash for-loop + objective score gate，Geoffrey Huntley 開源實作</li><li>Code review tools：Greptile、CodeRabbit、Macroscope（返回 /5 分數）</li><li>PR 上限經驗法則：&gt;~1,000 lines → review agent context 失效</li><li>Boris Cherny（Claude Code 工程師）：「barely prompts models directly anymore... his job is to build the loops」</li><li>PRD-driven spec pattern：<code>spec.md</code> / <code>PRD.md</code>；參考 github.com/snarktank/ai-dev-tasks</li></ul><h3 id="批判性觀察" tabindex="-1">批判性觀察 <a class="header-anchor" href="#批判性觀察" aria-label="Permalink to &quot;批判性觀察&quot;">​</a></h3><ol><li><strong>「客觀 vs 主觀」框架稍嫌二元</strong>：實務中多數任務是混合型；作者未提供灰色地帶的決策準則（如何判斷一個任務是否「夠客觀」）</li><li><strong>Code review loop 依賴第三方評分工具的可靠性</strong>：Greptile/CodeRabbit 的評分一致性、與人工 review 的相關性未被檢驗，直接用分數當 gate 有風險</li><li><strong>Token 成本論述缺乏量化</strong>：「burns fast」未附數字；對 Fable 5 era 的讀者來說，medium effort 的實際 token 成本需要自行估算</li></ol><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>8/10</td><td>Ralph loop bash pattern + code review gate 可直接部署</td></tr><tr><td>B. 創新性 (20%)</td><td>6/10</td><td>觀點框架清晰但 Boris Cherny 引用已廣泛流傳，無獨創發現</td></tr><tr><td>C. 證據品質 (20%)</td><td>6/10</td><td>論點紮實但缺乏量化數據；token 成本未具體化</td></tr><tr><td>D. 技術深度 (15%)</td><td>7/10</td><td>Ralph loop + score gate + 1000-line context limit 有實戰洞察</td></tr><tr><td>E. 泛化性 (15%)</td><td>8/10</td><td>適用所有 agent workflow 設計者，不限語言/框架</td></tr><tr><td><strong>加權總分</strong></td><td><strong>7.05/10</strong></td><td>8×0.3+6×0.2+6×0.2+7×0.15+8×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：Rule <strong>理由</strong>：Loop 適用邊界（客觀目標 + exit condition + PR 大小限制）是可直接入庫的設計原則。</p>`,37)])])}const g=t(s,[["render",i]]);export{c as __pageData,g as default};
